@JvmInline value class ExpenseId(val value: String)
data class Money(val minor: Long) { init { require(minor >= 0) } }
data class Expense(val id: ExpenseId, val category: String, val amount: Money)
class ExpenseBook {
    private val values = mutableListOf<Expense>()
    fun add(expense: Expense) { require(values.none { it.id == expense.id }); values += expense }
    fun total(): Long = values.sumOf { it.amount.minor }
}
